"""The demo, run 6: open() prints all seven cells on one fresh model (Z113 clean seed 12) and, for contrast, the seven cells on a true memoriser.
Everything from cached Run-6 results plus a live orbit-coherence pass.  CPU."""
import sys, os, json, glob, time
os.environ.setdefault('WB_DEV', 'cpu')
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import numpy as np, torch
from analysis.run4_z113 import load, group
from whiteboxtopo.symmetry_finite import cycle_coordinate, characters
from whiteboxtopo.knowledge import orbit_stats, z113_group
from systems.z113 import P, NULL, EQ, build_data
Z = json.load(open('results/run6/z113_finals.json'))
for run, seed, mode, frac in (('r6_z113_clean_s12', 12, 'clean', .3), ('r6_z113_scrambled_decoy_s15', 15, 'scrambled_decoy', .3)):
    t0 = time.time(); m = load(sorted(glob.glob(f'runs/{run}/ckpt_*.pt'))[-1], seed); r = Z[run]; _, gr, sig = group(m); u = r['u']
    d = build_data(seed, mode, frac=frac); tk = d['test_toks'][:400].copy(); tk[:, 2] = NULL; st = orbit_stats(lambda t: m(t), torch.as_tensor(tk), z113_group(u))
    print('=' * 118); print(f"open(Z113 {mode} seed {seed})  — the seven cells")
    print(f"  P1 what it learned      : " + (f"the cyclic group generated by translation by {u} (full 113-cycle found from outputs alone); characters at {[c['freq'] for c in characters(m.W_E[:P].numpy(), cycle_coordinate(sig), top=5)]}" if sig is not None else "no group (no full 113-cycle among accepted permutations)"))
    print(f"  P2 why this decision    : orbit coherence on 400 held-out inputs: κ = {st['kappa'].mean():.3f} (the prediction transforms with the group on {100*st['kappa'].mean():.0f}% of orbit elements)")
    s = r['slot_share']; print(f"  P3 spurious structure   : slot shares (a, b, hint) = ({s[0]:.3f}, {s[1]:.3f}, {s[2]:.3f}); dominant-direction flag: {'slot ' + 'ab hint'.split()[int(np.argmax(s))] if max(s) > 0.8 else 'none'}")
    K = r['K']; print(f"  P4 what it does not know: κ median in-distribution {K['in_kappa_median']:.2f}; unknown (OOV token) κ mean {K['oov']['unknown_kappa_mean']:.2f} → AUROC {K['oov']['auroc_kappa']:.3f} (max-softmax {K['oov']['auroc_msp']:.3f}); p′=97 pairs are valid inputs → AUROC {K['p97']['auroc_kappa']:.2f}")
    F = r['F']; print(f"  P5 where it will fail   : Spearman(ε, failure radius) = {F['spearman_eps']:+.3f}; softmax margin {F['spearman_margin']:+.3f}; random-transformation null {F['spearman_eps_random_transforms']:+.3f}  → ε does not predict failure here")
    q = r['q_swap']; dl = r['connection']['delta']; und = [s[0] >= .4 and s[1] >= .4 and s[2] <= .05, q < .10, dl < -.25, sig is not None]
    print(f"  P6 understands?         : slot collapse {'yes' if und[0] else 'no'}, q(swap) = {q:.3f}, Δ depth slope = {dl:+.3f}, generator {'yes' if und[3] else 'no'}  → {'UNDERSTANDS (4/4)' if all(und) else 'MEMORISES (0/4)' if not any(und) else 'MIXED'}")
    sw = f'results/run6/sweep_{run}.json'
    if os.path.exists(sw):
        rows = sorted(json.load(open(sw)), key=lambda x: x['ckpt']); g = rows[0]['jump_ckpt']; cyc = [x for x in rows if x['full_cycle']]
        print(f"  P7 how it formed        : generator first accepted at checkpoint {cyc[0]['ckpt']} (test acc {cyc[0]['test_acc']:.2f}); largest accuracy jump at {g}; lead {g - cyc[0]['ckpt']:+d}; present on {100*np.mean([x['full_cycle'] for x in rows if x['ckpt'] > cyc[0]['ckpt']]):.0f}% of later checkpoints")
    else:
        print(f"  P7 how it formed        : no generator at any of 51 checkpoints (memoriser; not swept in Run 6 — Run 5 result)")
    print(f"  [{time.time()-t0:.0f}s]")
